   pure subroutine pcsi1210(gt, lo, hi, nseg, sOff, sA, sNB, sOA, sOB, sPA, sPB, sD, &
                      npair, sp_i, sp_j, sp_q, thresh, pcut, jfac, kfac, omega, dsh, nbas, nao, sh_l, ao_off, &
                      nqp, qp_z, qp_c, qp_px, qp_py, qp_pz, &
                      sq_ax, sq_ay, sq_az, sq_abx, sq_aby, sq_abz, sq_n, &
                      ndens, dmat, jmat)
      !$acc routine seq
      integer(int64), intent(in) :: gt
      integer,  intent(in)    :: lo, hi, nseg, npair, nbas, nao
      integer(int64), intent(in) :: sOff(nseg + 1)
      integer,  intent(in)    :: sA(nseg), sNB(nseg), sOA(nseg), sOB(nseg)
      integer,  intent(in)    :: sPA(nseg), sPB(nseg)
      !! Primitive base of the bra bin / ket bin, into qp_* below -- the
      !! bin-interleaved second copy of pp_p/pp_r/pp_ra/pp_c, laid out so
      !! that lane iab's primitive k sits next to lane iab+1's.
      logical,  intent(in)    :: sD(nseg)
      integer,  intent(in)    :: sp_i(npair), sp_j(npair)
      real(dp), intent(in)    :: sp_q(npair), thresh
      real(dp), intent(in)    :: pcut
      !! Cutoff for the primitive-quartet prescreen: a primitive quartet
      !! whose prefactor cannot reach this is skipped before the Boys
      !! function. It is a fraction of `thresh`, and a runtime argument
      !! rather than a literal so the fraction can be measured against the
      !! energy it costs instead of guessed once.
      !!
      !! Tested against the UNATTENUATED prefactor (the primitive loop below
      !! computes `pref` before `theta`, deliberately): erf(omega*r12)/r12 is
      !! pointwise smaller than 1/r12, so the Coulomb prefactor bounds the
      !! attenuated integral too, just loosely at omega > 0. Still a valid
      !! prescreen, never a missed quartet -- see trc_screen.F90 for the
      !! Schwarz bound's identical reasoning.
      real(dp), intent(in)    :: jfac, kfac
      !! Coulomb and exchange scalings. Per call, so they fold into the six
      !! atomic updates and the digestion stays folded -- separating J and K
      !! into two matrices to scale them would give back FOCK6's 22%.
      real(dp), intent(in)    :: omega
      !! Range-separation parameter, bohr^-1. Zero (the default every caller
      !! but wB97X-V's long-range exchange pass uses) is today's Coulomb
      !! operator; omega > 0 attenuates it to erf(omega*r12)/r12. A plain
      !! scalar, not optional, so it costs one comparison per primitive
      !! quartet and nothing else -- see the primitive loop below, where
      !! omega == 0 makes every quantity it touches bit-identical to the
      !! unattenuated value.
      real(dp), intent(in)    :: dsh(nbas, nbas)
      integer,  intent(in)    :: sh_l(nbas), ao_off(nbas)
      integer,  intent(in)    :: nqp
      !! Bin-interleaved primitive-pair data: qp_z/qp_c/qp_px/qp_py/qp_pz
      !! are what the kernel reads for the bra/ket primitives, at
      !! sPA(seg) + (k-1)*sA(seg) + iab (bra) or sPB(seg) + (k-1)*sNB(seg)
      !! + icd (ket).
      real(dp), intent(in)    :: qp_z(nqp), qp_c(nqp)
      real(dp), intent(in)    :: qp_px(nqp), qp_py(nqp), qp_pz(nqp)
      real(dp), intent(in)    :: sq_ax(npair), sq_ay(npair), sq_az(npair)
      !! Per pair slot, aligned with sp_i/sp_j/sp_q: the A centre, A - B,
      !! and the real kept primitive-pair count pp_n(key) gave before.
      real(dp), intent(in)    :: sq_abx(npair), sq_aby(npair), sq_abz(npair)
      integer,  intent(in)    :: sq_n(npair)
      integer,  intent(in)    :: ndens
      real(dp), intent(in)    :: dmat(ndens, nao, nao)
      real(dp), intent(inout) :: jmat(ndens, nao, nao)
      integer :: p, q, mid, seg, t, iab, icd, si, sj, sk, sl
      integer(int64) :: nsa, u, kx
      real(dp) :: qcut, bnd
      integer :: slotab, slotcd, nab, ncd
      integer :: kp, kq, k1, k2
      integer :: d, x, cur, ia, ib, ic, id, idx, idens
      integer :: mu, nu, lam, sig, mui, nuj, lamk, sigl
      logical :: dij, dkl, dpq
      real(dp) :: zeta, eta, zpe, rho, tval, pref, wc
      real(dp) :: theta, rho_theta
      real(dp) :: pqx, pqy, pqz, pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re, sc, vv
      real(dp) :: abx, aby, abz, cdx, cdy, cdz
      real(dp) :: rpx, rpy, rpz, rzeta, reta, rzpe
      real(dp) :: f(0:BOYS_MMAX)
      integer  :: bi, bj, bbase
      real(dp) :: bx, bx2, b0, b1, b2, btt, bet
      real(dp) :: v(80, 0:1), g1(80), vbuf(54)
      real(dp) :: wq, w, wab, cabmax, ccdmax, qchunk
      logical  :: same_ab, same_cd, same_pair
      real(dp) :: jab(18), jcd(3), kac(9)
      real(dp) :: kad(3), kbc(18), kbd(6)
      real(dp) :: dab(18), dcd(3), dac(9)
      real(dp) :: dad(3), dbc(18), dbd(6)

      ! locate the segment
         p = lo; q = hi
         do while (p < q)
            mid = (p + q + 1)/2
            if (sOff(mid) < gt) then
               p = mid
            else
               q = mid - 1
            end if
         end do
         seg = p
         t = int(gt - sOff(seg))

         ! KET-UNIFORM DECODE. The bra pair index runs fastest, so the 32
         ! threads of a warp hold 32 bra pairs against ONE ket pair, and the
         ! loads of the inner primitive loop -- the ket side -- are the same
         ! address across the warp: one L1 transaction, broadcast. With the
         ! ket index fastest, as this was, every thread pulled its own ket
         ! record per primitive quartet and Nsight Compute had (ss|ss) at 96%
         ! of L1 throughput with a 28% hit rate. The bra loads now diverge
         ! instead, once per bra primitive rather than once per quartet.
         ! On a symmetric segment the pairs are enumerated column by column,
         ! iab >= icd, with the same closed form inverted.
         if (sD(seg)) then
            nsa = int(sA(seg), int64)
            u = int(t - 1, int64)
            kx = int((real(2*nsa + 1, dp) - sqrt(real(2*nsa + 1, dp)**2 - 8.0_dp*real(u, dp)))/2.0_dp, int64)
            if (kx < 0) kx = 0
            do while (kx > 0)
               if ((kx*(2*nsa + 1) - kx*kx)/2 <= u) exit
               kx = kx - 1
            end do
            do while (((kx + 1)*(2*nsa + 1) - (kx + 1)*(kx + 1))/2 <= u)
               kx = kx + 1
            end do
            icd = int(kx) + 1
            iab = icd + int(u - (kx*(2*nsa + 1) - kx*kx)/2)
         else
            icd = (t - 1)/sA(seg) + 1
            iab = t - (icd - 1)*sA(seg)
         end if

         ! exact Schwarz, per quartet.  The host bin-pair test is only
         ! decade-granular (`int(-log10 Q)` clamped to 9) and therefore admits
         ! up to two decades too much; at RNA3 that was 46% of all quartets.
         qcut = sp_q(sOA(seg) + iab)*sp_q(sOB(seg) + icd)
         if (qcut <= thresh) return

         si = sp_i(sOA(seg) + iab); sj = sp_j(sOA(seg) + iab)
         sk = sp_i(sOB(seg) + icd); sl = sp_j(sOB(seg) + icd)

         ! Density-weighted screen.  What actually enters the Fock matrix is
         ! Q_ab Q_cd times a density block, so a quartet whose integrals are
         ! above threshold still contributes nothing if every density block it
         ! multiplies is negligible.  The J terms carry a factor 4 from the
         ! Coulomb degeneracy, the K terms 1.  For a converged density on an
         ! extended molecule this is where most of the screening comes from --
         ! with a flat model density it correctly fires on nothing.
         if (qcut*max(4.0_dp*dsh(si, sj), 4.0_dp*dsh(sk, sl), &
                      dsh(si, sk), dsh(si, sl), &
                      dsh(sj, sk), dsh(sj, sl)) <= thresh) return

         same_ab = (si == sj); same_cd = (sk == sl)
         same_pair = sD(seg) .and. (iab == icd)

         slotab = sOA(seg) + iab; slotcd = sOB(seg) + icd
         nab = sq_n(slotab); ncd = sq_n(slotcd)

         abx = sq_abx(slotab); aby = sq_aby(slotab); abz = sq_abz(slotab)
         cdx = sq_abx(slotcd); cdy = sq_aby(slotcd); cdz = sq_abz(slotcd)

            do x = 1, 80
               g1(x) = 0.0_dp
            end do
            do k1 = 1, nab
               kp = sPA(seg) + (k1 - 1)*sA(seg) + iab
               zeta = qp_z(kp)
               bnd = TWO_PI_2_5*abs(qp_c(kp))/(zeta*sqrt(zeta))
               if (bnd*abs(qp_c(sPB(seg) + icd))/qp_z(sPB(seg) + icd) <= pcut) cycle
               ! Bra-only quantities, out of the ket loop. They depend on
               ! kp alone and were being reloaded and recomputed once per
               ! KET primitive, which on a deeply contracted shell pair is
               ! 144 times over for values that never change. The compiler
               ! does not lift them, presumably because it cannot prove the
               ! loads invariant. Measured on (ps|ss) of the silica slice in
               ! cc-pVDZ: 3.21 s -> 2.29 s, with every other class in the
               ! same profile flat.
               rpx = qp_px(kp); rpy = qp_py(kp); rpz = qp_pz(kp)
               pax = rpx - sq_ax(slotab)
               pay = rpy - sq_ay(slotab)
               paz = rpz - sq_az(slotab)
               ! 1/zeta with them: the bra exponent does not change across
               ! the ket loop, so its reciprocal is one division per bra
               ! primitive rather than three per primitive QUARTET.
               rzeta = 1.0_dp/zeta
               oo2z = 0.5_dp*rzeta
               do k2 = 1, ncd
                  kq = sPB(seg) + (k2 - 1)*sNB(seg) + icd
                  eta = qp_z(kq)
                  zpe = zeta + eta
                  ! PRIMITIVE-QUARTET PRESCREEN. The prefactor bounds the
                  ! primitive (ss|ss) integral, and with the normalisation
                  ! in the coefficients it bounds the higher ones to within
                  ! the polynomial factors the cutoff's three decades of
                  ! margin cover. Tested before the Boys function and the
                  ! VRR, which is nearly all of a primitive quartet's cost;
                  ! on a generally contracted basis two thirds of the
                  ! quartets that survive the pair pruning die here.
                  pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*qp_c(kp)*qp_c(kq)
                  if (bnd*abs(qp_c(kq))/eta <= pcut) exit
                  if (abs(pref) <= pcut) cycle
                  ! One reciprocal each for eta and zeta+eta, then multiply.
                  ! This loop used to issue ten double-precision divisions
                  ! per primitive quartet -- rho, three for the W centre,
                  ! three halves, two rho ratios and the prefactor -- against
                  ! a recurrence that for the light classes is five lines.
                  ! Division has no fast reciprocal in double precision, so
                  ! that was the arithmetic, not the recurrence.
                  reta = 1.0_dp/eta
                  rzpe = 1.0_dp/zpe
                  rho = zeta*eta*rzpe
                  ! RANGE SEPARATION. erf(omega*r12)/r12 is the Coulomb
                  ! integral with rho replaced everywhere by
                  ! rho_theta = theta*rho, theta = omega^2/(rho + omega^2) --
                  ! the W centre (wpx/wqx below), the Boys argument tval, and
                  ! the oo2ze/rz/re VRR coefficients -- and the prefactor
                  ! picks up a sqrt(theta) factor. oo2z and oo2e come from
                  ! zeta and eta alone and are not touched: the kernels do
                  ! NOT use rho consistently, and those two are the
                  ! quantities that only equal a rho expression through
                  ! rho*(zeta+eta) = zeta*eta, not through rho itself.
                  !
                  ! omega == 0 sets theta = 1.0_dp exactly, so
                  ! rho_theta equals rho bit-for-bit and every "theta*" below
                  ! is an exact multiply by one: the attenuated path costs
                  ! this one branch and is otherwise identical to the
                  ! Coulomb result, to the last bit.
                  if (omega > 0.0_dp) then
                     theta = omega*omega/(rho + omega*omega)
                  else
                     theta = 1.0_dp
                  end if
                  rho_theta = theta*rho
                  pqx = rpx - qp_px(kq)
                  pqy = rpy - qp_py(kq)
                  pqz = rpz - qp_pz(kq)
                  qcx = qp_px(kq) - sq_ax(slotcd)
                  qcy = qp_py(kq) - sq_ay(slotcd)
                  qcz = qp_pz(kq) - sq_az(slotcd)
                  wc = (zeta*rpx + eta*qp_px(kq))*rzpe
                  wpx = wc - qp_px(kp); wqx = wc - qp_px(kq)
                  wc = (zeta*rpy + eta*qp_py(kq))*rzpe
                  wpy = wc - qp_py(kp); wqy = wc - qp_py(kq)
                  wc = (zeta*rpz + eta*qp_pz(kq))*rzpe
                  wpz = wc - qp_pz(kp); wqz = wc - qp_pz(kq)
                  wpx = theta*wpx; wpy = theta*wpy; wpz = theta*wpz
                  wqx = theta*wqx; wqy = theta*wqy; wqz = theta*wqz
                  tval = rho_theta*(pqx*pqx + pqy*pqy + pqz*pqz)

                  if (tval >= BOYS_TMAX) then
                  btt = 1.0_dp/tval
                  f(0) = 0.88622692545275801365_dp*sqrt(btt)
                  bet = 0.0_dp
                  f(1) = 1.0_dp*f(0)*(0.5_dp*btt)
                  f(2) = 3.0_dp*f(1)*(0.5_dp*btt)
                  f(3) = 5.0_dp*f(2)*(0.5_dp*btt)
                  f(4) = 7.0_dp*f(3)*(0.5_dp*btt)
               else
                  bi = int(tval*BOYS_DTINV)
                  bi = min(bi, BOYS_NGRID - 1)
                  bx = 2.0_dp*(tval - real(bi, dp)*BOYS_DT)*BOYS_DTINV - 1.0_dp
                  bx2 = 2.0_dp*bx
                  bbase = bi*(BOYS_MMAX + 1)*(BOYS_NCHEB + 1)
                  bj = bbase + 4*(BOYS_NCHEB + 1)
                  b1 = boys_table(bj + BOYS_NCHEB + 1)
                  b2 = 0.0_dp
                  b0 = bx2*b1 - b2 + boys_table(bj + 5); b2 = b1; b1 = b0
                  b0 = bx2*b1 - b2 + boys_table(bj + 4); b2 = b1; b1 = b0
                  b0 = bx2*b1 - b2 + boys_table(bj + 3); b2 = b1; b1 = b0
                  b0 = bx2*b1 - b2 + boys_table(bj + 2); b2 = b1; b1 = b0
                  f(4) = bx*b1 - b2 + boys_table(bj + 1)
                  bet = exp(-tval)
                  btt = 2.0_dp*tval
                  f(3) = (btt*f(4) + bet)*(0.14285714285714285_dp)
                  f(2) = (btt*f(3) + bet)*(0.2_dp)
                  f(1) = (btt*f(2) + bet)*(0.3333333333333333_dp)
                  f(0) = (btt*f(1) + bet)*(1.0_dp)
               end if

                  pref = pref*sqrt(theta)
                  oo2e = 0.5_dp*reta; oo2ze = theta*(0.5_dp*rzpe)
                  rz = rho_theta*rzeta; re = rho_theta*reta

               ! --- level m = 4 ---
            v(1,0) = pref*f(4)
            ! --- level m = 3 ---
            v(1,1) = pref*f(3)
            v(2,1) = pax*v(1,1) + wpx*v(1,0)
            v(3,1) = pay*v(1,1) + wpy*v(1,0)
            v(4,1) = paz*v(1,1) + wpz*v(1,0)
            ! --- level m = 2 ---
            v(1,0) = pref*f(2)
            v(2,0) = pax*v(1,0) + wpx*v(1,1)
            v(3,0) = pay*v(1,0) + wpy*v(1,1)
            v(4,0) = paz*v(1,0) + wpz*v(1,1)
            v(5,0) = pax*v(2,0) + wpx*v(2,1) &
               + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
            v(7,0) = pax*v(4,0) + wpx*v(4,1)
            v(8,0) = pay*v(3,0) + wpy*v(3,1) &
               + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
            v(10,0) = paz*v(4,0) + wpz*v(4,1) &
               + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
            v(44,0) = qcy*v(4,0) + wqy*v(4,1)
            ! --- level m = 1 ---
            v(1,1) = pref*f(1)
            v(2,1) = pax*v(1,1) + wpx*v(1,0)
            v(3,1) = pay*v(1,1) + wpy*v(1,0)
            v(4,1) = paz*v(1,1) + wpz*v(1,0)
            v(5,1) = pax*v(2,1) + wpx*v(2,0) &
               + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
            v(6,1) = pax*v(3,1) + wpx*v(3,0)
            v(7,1) = pax*v(4,1) + wpx*v(4,0)
            v(8,1) = pay*v(3,1) + wpy*v(3,0) &
               + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
            v(9,1) = pay*v(4,1) + wpy*v(4,0)
            v(10,1) = paz*v(4,1) + wpz*v(4,0) &
               + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
            v(22,1) = qcx*v(2,1) + wqx*v(2,0) &
               + 1.0_dp*oo2ze*v(1,0)
            v(42,1) = qcy*v(2,1) + wqy*v(2,0)
            v(43,1) = qcy*v(3,1) + wqy*v(3,0) &
               + 1.0_dp*oo2ze*v(1,0)
            v(44,1) = qcy*v(4,1) + wqy*v(4,0)
            v(62,1) = qcz*v(2,1) + wqz*v(2,0)
            v(14,1) = pax*v(8,1) + wpx*v(8,0)
            v(15,1) = pay*v(7,1) + wpy*v(7,0)
            v(17,1) = pay*v(8,1) + wpy*v(8,0) &
               + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
            v(18,1) = paz*v(8,1) + wpz*v(8,0)
            v(20,1) = paz*v(10,1) + wpz*v(10,0) &
               + 2.0_dp*oo2z*(v(4,1) - rz*v(4,0))
            v(25,1) = qcx*v(5,1) + wqx*v(5,0) &
               + 2.0_dp*oo2ze*v(2,0)
            v(30,1) = qcx*v(10,1) + wqx*v(10,0)
            v(45,1) = qcy*v(5,1) + wqy*v(5,0)
            v(47,1) = pax*v(44,1) + wpx*v(44,0)
            v(49,1) = pay*v(44,1) + wpy*v(44,0) &
               + 1.0_dp*oo2ze*v(4,0)
            v(65,1) = qcz*v(5,1) + wqz*v(5,0)
            v(70,1) = qcz*v(10,1) + wqz*v(10,0) &
               + 2.0_dp*oo2ze*v(4,0)
            ! --- level m = 0 ---
            v(1,0) = pref*f(0)
            v(2,0) = pax*v(1,0) + wpx*v(1,1)
            v(3,0) = pay*v(1,0) + wpy*v(1,1)
            v(4,0) = paz*v(1,0) + wpz*v(1,1)
            v(5,0) = pax*v(2,0) + wpx*v(2,1) &
               + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
            v(8,0) = pay*v(3,0) + wpy*v(3,1) &
               + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
            v(9,0) = pay*v(4,0) + wpy*v(4,1)
            v(10,0) = paz*v(4,0) + wpz*v(4,1) &
               + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
            v(22,0) = qcx*v(2,0) + wqx*v(2,1) &
               + 1.0_dp*oo2ze*v(1,1)
            v(23,0) = qcx*v(3,0) + wqx*v(3,1)
            v(24,0) = qcx*v(4,0) + wqx*v(4,1)
            v(42,0) = qcy*v(2,0) + wqy*v(2,1)
            v(43,0) = qcy*v(3,0) + wqy*v(3,1) &
               + 1.0_dp*oo2ze*v(1,1)
            v(44,0) = qcy*v(4,0) + wqy*v(4,1)
            v(62,0) = qcz*v(2,0) + wqz*v(2,1)
            v(63,0) = qcz*v(3,0) + wqz*v(3,1)
            v(64,0) = qcz*v(4,0) + wqz*v(4,1) &
               + 1.0_dp*oo2ze*v(1,1)
            v(14,0) = pax*v(8,0) + wpx*v(8,1)
            v(15,0) = pax*v(9,0) + wpx*v(9,1)
            v(17,0) = pay*v(8,0) + wpy*v(8,1) &
               + 2.0_dp*oo2z*(v(3,0) - rz*v(3,1))
            v(18,0) = paz*v(8,0) + wpz*v(8,1)
            v(20,0) = paz*v(10,0) + wpz*v(10,1) &
               + 2.0_dp*oo2z*(v(4,0) - rz*v(4,1))
            v(25,0) = qcx*v(5,0) + wqx*v(5,1) &
               + 2.0_dp*oo2ze*v(2,1)
            v(26,0) = pay*v(22,0) + wpy*v(22,1)
            v(27,0) = paz*v(22,0) + wpz*v(22,1)
            v(28,0) = qcx*v(8,0) + wqx*v(8,1)
            v(29,0) = qcx*v(9,0) + wqx*v(9,1)
            v(30,0) = qcx*v(10,0) + wqx*v(10,1)
            v(45,0) = qcy*v(5,0) + wqy*v(5,1)
            v(46,0) = pax*v(43,0) + wpx*v(43,1)
            v(47,0) = pax*v(44,0) + wpx*v(44,1)
            v(48,0) = qcy*v(8,0) + wqy*v(8,1) &
               + 2.0_dp*oo2ze*v(3,1)
            v(49,0) = paz*v(43,0) + wpz*v(43,1)
            v(50,0) = qcy*v(10,0) + wqy*v(10,1)
            v(65,0) = qcz*v(5,0) + wqz*v(5,1)
            v(66,0) = pay*v(62,0) + wpy*v(62,1)
            v(67,0) = paz*v(62,0) + wpz*v(62,1) &
               + 1.0_dp*oo2ze*v(2,1)
            v(68,0) = qcz*v(8,0) + wqz*v(8,1)
            v(69,0) = qcz*v(9,0) + wqz*v(9,1) &
               + 1.0_dp*oo2ze*v(3,1)
            v(70,0) = qcz*v(10,0) + wqz*v(10,1) &
               + 2.0_dp*oo2ze*v(4,1)
            v(31,0) = pax*v(25,0) + wpx*v(25,1) &
               + 2.0_dp*oo2z*(v(22,0) - rz*v(22,1)) &
               + 1.0_dp*oo2ze*v(5,1)
            v(32,0) = pay*v(25,0) + wpy*v(25,1)
            v(33,0) = paz*v(25,0) + wpz*v(25,1)
            v(34,0) = qcx*v(14,0) + wqx*v(14,1) &
               + 1.0_dp*oo2ze*v(8,1)
            v(35,0) = qcx*v(15,0) + wqx*v(15,1) &
               + 1.0_dp*oo2ze*v(9,1)
            v(36,0) = pax*v(30,0) + wpx*v(30,1) &
               + 1.0_dp*oo2ze*v(10,1)
            v(37,0) = qcx*v(17,0) + wqx*v(17,1)
            v(38,0) = qcx*v(18,0) + wqx*v(18,1)
            v(39,0) = pay*v(30,0) + wpy*v(30,1)
            v(40,0) = qcx*v(20,0) + wqx*v(20,1)
            v(51,0) = pax*v(45,0) + wpx*v(45,1) &
               + 2.0_dp*oo2z*(v(42,0) - rz*v(42,1))
            v(52,0) = pay*v(45,0) + wpy*v(45,1) &
               + 1.0_dp*oo2ze*v(5,1)
            v(53,0) = paz*v(45,0) + wpz*v(45,1)
            v(54,0) = qcy*v(14,0) + wqy*v(14,1) &
               + 2.0_dp*oo2ze*v(6,1)
            v(55,0) = pax*v(49,0) + wpx*v(49,1)
            v(56,0) = paz*v(47,0) + wpz*v(47,1) &
               + 1.0_dp*oo2z*(v(42,0) - rz*v(42,1))
            v(57,0) = qcy*v(17,0) + wqy*v(17,1) &
               + 3.0_dp*oo2ze*v(8,1)
            v(58,0) = qcy*v(18,0) + wqy*v(18,1) &
               + 2.0_dp*oo2ze*v(9,1)
            v(59,0) = paz*v(49,0) + wpz*v(49,1) &
               + 1.0_dp*oo2z*(v(43,0) - rz*v(43,1))
            v(60,0) = qcy*v(20,0) + wqy*v(20,1)
            v(71,0) = pax*v(65,0) + wpx*v(65,1) &
               + 2.0_dp*oo2z*(v(62,0) - rz*v(62,1))
            v(72,0) = pay*v(65,0) + wpy*v(65,1)
            v(73,0) = paz*v(65,0) + wpz*v(65,1) &
               + 1.0_dp*oo2ze*v(5,1)
            v(74,0) = qcz*v(14,0) + wqz*v(14,1)
            v(75,0) = qcz*v(15,0) + wqz*v(15,1) &
               + 1.0_dp*oo2ze*v(6,1)
            v(76,0) = pax*v(70,0) + wpx*v(70,1)
            v(77,0) = qcz*v(17,0) + wqz*v(17,1)
            v(78,0) = qcz*v(18,0) + wqz*v(18,1) &
               + 1.0_dp*oo2ze*v(8,1)
            v(79,0) = pay*v(70,0) + wpy*v(70,1)
            v(80,0) = qcz*v(20,0) + wqz*v(20,1) &
               + 3.0_dp*oo2ze*v(10,1)
               cur = 0
                  do x = 1, 80
                     g1(x) = g1(x) + v(x, cur)
                  end do
               end do
            end do
         ! Single column on every side: the canonical enumeration and the
         ! degeneracy weights are the pair-level ones.
         dij = .not. same_ab
         dkl = .not. same_cd
         dpq = .not. same_pair
         mui = ao_off(si); nuj = ao_off(sj); lamk = ao_off(sk); sigl = ao_off(sl)

         ! --- HRR ---
         vbuf(1) = abx*abx*g1(22) &
            + 2.0_dp*abx*g1(25) &
            + g1(31)
         vbuf(2) = abx*abx*g1(23) &
            + 2.0_dp*abx*g1(26) &
            + g1(32)
         vbuf(3) = abx*abx*g1(24) &
            + 2.0_dp*abx*g1(27) &
            + g1(33)
         vbuf(4) = abx*aby*g1(22) &
            + abx*g1(26) &
            + aby*g1(25) &
            + g1(32)
         vbuf(5) = abx*aby*g1(23) &
            + abx*g1(28) &
            + aby*g1(26) &
            + g1(34)
         vbuf(6) = abx*aby*g1(24) &
            + abx*g1(29) &
            + aby*g1(27) &
            + g1(35)
         vbuf(7) = abx*abz*g1(22) &
            + abx*g1(27) &
            + abz*g1(25) &
            + g1(33)
         vbuf(8) = abx*abz*g1(23) &
            + abx*g1(29) &
            + abz*g1(26) &
            + g1(35)
         vbuf(9) = abx*abz*g1(24) &
            + abx*g1(30) &
            + abz*g1(27) &
            + g1(36)
         vbuf(10) = aby*aby*g1(22) &
            + 2.0_dp*aby*g1(26) &
            + g1(34)
         vbuf(11) = aby*aby*g1(23) &
            + 2.0_dp*aby*g1(28) &
            + g1(37)
         vbuf(12) = aby*aby*g1(24) &
            + 2.0_dp*aby*g1(29) &
            + g1(38)
         vbuf(13) = aby*abz*g1(22) &
            + aby*g1(27) &
            + abz*g1(26) &
            + g1(35)
         vbuf(14) = aby*abz*g1(23) &
            + aby*g1(29) &
            + abz*g1(28) &
            + g1(38)
         vbuf(15) = aby*abz*g1(24) &
            + aby*g1(30) &
            + abz*g1(29) &
            + g1(39)
         vbuf(16) = abz*abz*g1(22) &
            + 2.0_dp*abz*g1(27) &
            + g1(36)
         vbuf(17) = abz*abz*g1(23) &
            + 2.0_dp*abz*g1(29) &
            + g1(39)
         vbuf(18) = abz*abz*g1(24) &
            + 2.0_dp*abz*g1(30) &
            + g1(40)
         vbuf(19) = abx*abx*g1(42) &
            + 2.0_dp*abx*g1(45) &
            + g1(51)
         vbuf(20) = abx*abx*g1(43) &
            + 2.0_dp*abx*g1(46) &
            + g1(52)
         vbuf(21) = abx*abx*g1(44) &
            + 2.0_dp*abx*g1(47) &
            + g1(53)
         vbuf(22) = abx*aby*g1(42) &
            + abx*g1(46) &
            + aby*g1(45) &
            + g1(52)
         vbuf(23) = abx*aby*g1(43) &
            + abx*g1(48) &
            + aby*g1(46) &
            + g1(54)
         vbuf(24) = abx*aby*g1(44) &
            + abx*g1(49) &
            + aby*g1(47) &
            + g1(55)
         vbuf(25) = abx*abz*g1(42) &
            + abx*g1(47) &
            + abz*g1(45) &
            + g1(53)
         vbuf(26) = abx*abz*g1(43) &
            + abx*g1(49) &
            + abz*g1(46) &
            + g1(55)
         vbuf(27) = abx*abz*g1(44) &
            + abx*g1(50) &
            + abz*g1(47) &
            + g1(56)
         vbuf(28) = aby*aby*g1(42) &
            + 2.0_dp*aby*g1(46) &
            + g1(54)
         vbuf(29) = aby*aby*g1(43) &
            + 2.0_dp*aby*g1(48) &
            + g1(57)
         vbuf(30) = aby*aby*g1(44) &
            + 2.0_dp*aby*g1(49) &
            + g1(58)
         vbuf(31) = aby*abz*g1(42) &
            + aby*g1(47) &
            + abz*g1(46) &
            + g1(55)
         vbuf(32) = aby*abz*g1(43) &
            + aby*g1(49) &
            + abz*g1(48) &
            + g1(58)
         vbuf(33) = aby*abz*g1(44) &
            + aby*g1(50) &
            + abz*g1(49) &
            + g1(59)
         vbuf(34) = abz*abz*g1(42) &
            + 2.0_dp*abz*g1(47) &
            + g1(56)
         vbuf(35) = abz*abz*g1(43) &
            + 2.0_dp*abz*g1(49) &
            + g1(59)
         vbuf(36) = abz*abz*g1(44) &
            + 2.0_dp*abz*g1(50) &
            + g1(60)
         vbuf(37) = abx*abx*g1(62) &
            + 2.0_dp*abx*g1(65) &
            + g1(71)
         vbuf(38) = abx*abx*g1(63) &
            + 2.0_dp*abx*g1(66) &
            + g1(72)
         vbuf(39) = abx*abx*g1(64) &
            + 2.0_dp*abx*g1(67) &
            + g1(73)
         vbuf(40) = abx*aby*g1(62) &
            + abx*g1(66) &
            + aby*g1(65) &
            + g1(72)
         vbuf(41) = abx*aby*g1(63) &
            + abx*g1(68) &
            + aby*g1(66) &
            + g1(74)
         vbuf(42) = abx*aby*g1(64) &
            + abx*g1(69) &
            + aby*g1(67) &
            + g1(75)
         vbuf(43) = abx*abz*g1(62) &
            + abx*g1(67) &
            + abz*g1(65) &
            + g1(73)
         vbuf(44) = abx*abz*g1(63) &
            + abx*g1(69) &
            + abz*g1(66) &
            + g1(75)
         vbuf(45) = abx*abz*g1(64) &
            + abx*g1(70) &
            + abz*g1(67) &
            + g1(76)
         vbuf(46) = aby*aby*g1(62) &
            + 2.0_dp*aby*g1(66) &
            + g1(74)
         vbuf(47) = aby*aby*g1(63) &
            + 2.0_dp*aby*g1(68) &
            + g1(77)
         vbuf(48) = aby*aby*g1(64) &
            + 2.0_dp*aby*g1(69) &
            + g1(78)
         vbuf(49) = aby*abz*g1(62) &
            + aby*g1(67) &
            + abz*g1(66) &
            + g1(75)
         vbuf(50) = aby*abz*g1(63) &
            + aby*g1(69) &
            + abz*g1(68) &
            + g1(78)
         vbuf(51) = aby*abz*g1(64) &
            + aby*g1(70) &
            + abz*g1(69) &
            + g1(79)
         vbuf(52) = abz*abz*g1(62) &
            + 2.0_dp*abz*g1(67) &
            + g1(76)
         vbuf(53) = abz*abz*g1(63) &
            + 2.0_dp*abz*g1(69) &
            + g1(79)
         vbuf(54) = abz*abz*g1(64) &
            + 2.0_dp*abz*g1(70) &
            + g1(80)

         !
         ! BLOCK-ACCUMULATED DIGESTION.
         !
         ! The previous form did six atomic updates and six scattered `dmat`
         ! loads PER CARTESIAN COMPONENT.  For (pp|pp) that is 81 components x
         ! 6 = 486 of each, per quartet, even though only six small BLOCKS of
         ! jmat and six of dmat are ever touched.
         !
         ! gpu4pyscf's rys_contract_jk.cu does it the other way round: pull the
         ! density blocks into registers once (`load_dm`), contract every
         ! component against them there (`dot_dm`), and write each output block
         ! out once.  Same arithmetic, an order of magnitude less traffic --
         ! 54 loads and 54 atomics for (pp|pp) instead of 486.
         !
         ! The degeneracy factors are per-quartet, so they collapse into one
         ! scalar applied as the components are consumed.
         !
         wq = 1.0_dp
         if (.not. dij) wq = wq*0.5_dp
         if (.not. dkl) wq = wq*0.5_dp
         if (.not. dpq) wq = wq*0.5_dp

         !
         ! J-ONLY DIGESTION, for kfac = 0 (a pure LDA/GGA functional, or the
         ! Coulomb-only pass of the response equations). The exchange half of
         ! the general digestion below is then four density-block gathers and
         ! four multiply-adds per component that all come out exactly
         ! 0.0_dp, plus four accumulator blocks held live for nothing. This
         ! copy drops them; its J statements are the general branch's,
         ! character for character, so every jmat element is bit-identical
         ! to what that branch would have produced. A separate branch and not
         ! a test inside the component loop: guarding the K updates per
         ! component was measured 22% slower on a hybrid (w20/6-31G* B3LYP,
         ! V100), because the test sits on the branch that is always taken.
         ! kfac is uniform over the launch, so no warp diverges here.
         !
         if (kfac == 0.0_dp) then
         do idens = 1, ndens

         do ib = 0, 5
            do ia = 0, 2
               dab(1 + ia + 3*ib) = dmat(idens, mui + ia, nuj + ib)
               jab(1 + ia + 3*ib) = 0.0_dp
            end do
         end do
         id = 0
            do ic = 0, 2
               dcd(1 + ic + 3*id) = dmat(idens, lamk + ic, sigl + id)
               jcd(1 + ic + 3*id) = 0.0_dp
            end do

         ! Spelled differently from the general branch, on purpose, and with
         ! the same arithmetic: the component index in closed form and the
         ! scaled integral inline rather than in `idx` and `sc`. A second
         ! counted loop fails to translate the Rys launch under nvfortran
         ! 26.5 ("Missing increment value", trc_pc_rys1102).
         id = 0
         do ic = 0, 2
         do ib = 0, 5
         do ia = 0, 2
            jab(1 + ia + 3*ib) = jab(1 + ia + 3*ib) &
                                    + 4.0_dp*jfac*(wq*vbuf(1 + ia + 3*ib + 18*ic + 54*id)) &
                                    *dcd(1 + ic + 3*id)
            jcd(1 + ic + 3*id) = jcd(1 + ic + 3*id) &
                                    + 4.0_dp*jfac*(wq*vbuf(1 + ia + 3*ib + 18*ic + 54*id)) &
                                    *dab(1 + ia + 3*ib)
         end do
         end do
         end do

         do ib = 0, 5
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, nuj + ib) = jmat(idens, mui + ia, nuj + ib) &
                                          + jab(1 + ia + 3*ib)
            end do
         end do
         id = 0
            do ic = 0, 2
               !$acc atomic update
               jmat(idens, lamk + ic, sigl + id) = jmat(idens, lamk + ic, sigl + id) &
                                            + jcd(1 + ic + 3*id)
            end do

         end do   ! idens
         else

         !
         ! BATCHED OVER DENSITIES.
         !
         ! The integral is formed once, in `vbuf`, and contracted against every
         ! density in the batch. In the coupled-perturbed equations that is the
         ! difference between one integral pass and a hundred: the dynamic
         ! polarizabilities need nine perturbations times twelve imaginary
         ! frequencies, each a Fock build on a different response density.
         !
         ! The density loop is OUTSIDE the block accumulators, not inside, and
         ! that is the whole trick. The six blocks are zeroed, filled and
         ! written per density, so REGISTER PRESSURE DOES NOT GROW WITH THE
         ! BATCH -- holding N sets of blocks at once would have cost 54 more
         ! doubles per density at (pp|pp) and 216 at (dd|dd), on a kernel
         ! already spilling. Cost is `eval + ndens*digest`, and the ceiling is
         ! one over the digestion fraction.
         !
         do idens = 1, ndens

         !
         ! jfac = 0 whenever the MD J engine forms J (always for a g basis):
         ! the Coulomb blocks are then zero-filled rather than gathered and
         ! their atomics skipped below. The component loop is left alone (a
         ! test inside it costs more than it saves, see the J-only note).
         ! jfac is uniform over the launch, so no warp diverges.
         !
         if (jfac /= 0.0_dp) then
         do ib = 0, 5
            do ia = 0, 2
               dab(1 + ia + 3*ib) = dmat(idens, mui + ia, nuj + ib)
               jab(1 + ia + 3*ib) = 0.0_dp
            end do
         end do
         do id = 0, 0
            do ic = 0, 2
               dcd(1 + ic + 3*id) = dmat(idens, lamk + ic, sigl + id)
               jcd(1 + ic + 3*id) = 0.0_dp
            end do
         end do
         else
         do ib = 0, 5
            do ia = 0, 2
               dab(1 + ia + 3*ib) = 0.0_dp
               jab(1 + ia + 3*ib) = 0.0_dp
            end do
         end do
         do id = 0, 0
            do ic = 0, 2
               dcd(1 + ic + 3*id) = 0.0_dp
               jcd(1 + ic + 3*id) = 0.0_dp
            end do
         end do
         end if
         do ic = 0, 2
            do ia = 0, 2
               dac(1 + ia + 3*ic) = dmat(idens, mui + ia, lamk + ic)
               kac(1 + ia + 3*ic) = 0.0_dp
            end do
         end do
         do id = 0, 0
            do ia = 0, 2
               dad(1 + ia + 3*id) = dmat(idens, mui + ia, sigl + id)
               kad(1 + ia + 3*id) = 0.0_dp
            end do
         end do
         do ic = 0, 2
            do ib = 0, 5
               dbc(1 + ib + 6*ic) = dmat(idens, nuj + ib, lamk + ic)
               kbc(1 + ib + 6*ic) = 0.0_dp
            end do
         end do
         do id = 0, 0
            do ib = 0, 5
               dbd(1 + ib + 6*id) = dmat(idens, nuj + ib, sigl + id)
               kbd(1 + ib + 6*id) = 0.0_dp
            end do
         end do

         idx = 0
         do id = 0, 0
         do ic = 0, 2
         do ib = 0, 5
         do ia = 0, 2
            idx = idx + 1
            sc = wq*vbuf(idx)
            jab(1 + ia + 3*ib) = jab(1 + ia + 3*ib) &
                                    + 4.0_dp*jfac*sc*dcd(1 + ic + 3*id)
            jcd(1 + ic + 3*id) = jcd(1 + ic + 3*id) &
                                    + 4.0_dp*jfac*sc*dab(1 + ia + 3*ib)
            kac(1 + ia + 3*ic) = kac(1 + ia + 3*ic) &
                                    - kfac*sc*dbd(1 + ib + 6*id)
            kad(1 + ia + 3*id) = kad(1 + ia + 3*id) &
                                    - kfac*sc*dbc(1 + ib + 6*ic)
            kbc(1 + ib + 6*ic) = kbc(1 + ib + 6*ic) &
                                    - kfac*sc*dad(1 + ia + 3*id)
            kbd(1 + ib + 6*id) = kbd(1 + ib + 6*id) &
                                    - kfac*sc*dac(1 + ia + 3*ic)
         end do
         end do
         end do
         end do

         if (jfac /= 0.0_dp) then
         do ib = 0, 5
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, nuj + ib) = jmat(idens, mui + ia, nuj + ib) &
                                          + jab(1 + ia + 3*ib)
            end do
         end do
         do id = 0, 0
            do ic = 0, 2
               !$acc atomic update
               jmat(idens, lamk + ic, sigl + id) = jmat(idens, lamk + ic, sigl + id) &
                                            + jcd(1 + ic + 3*id)
            end do
         end do
         end if
         do ic = 0, 2
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, lamk + ic) = jmat(idens, mui + ia, lamk + ic) &
                                           + kac(1 + ia + 3*ic)
            end do
         end do
         do id = 0, 0
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, sigl + id) = jmat(idens, mui + ia, sigl + id) &
                                           + kad(1 + ia + 3*id)
            end do
         end do
         do ic = 0, 2
            do ib = 0, 5
               !$acc atomic update
               jmat(idens, nuj + ib, lamk + ic) = jmat(idens, nuj + ib, lamk + ic) &
                                           + kbc(1 + ib + 6*ic)
            end do
         end do
         do id = 0, 0
            do ib = 0, 5
               !$acc atomic update
               jmat(idens, nuj + ib, sigl + id) = jmat(idens, nuj + ib, sigl + id) &
                                           + kbd(1 + ib + 6*id)
            end do
         end do

         end do   ! idens
         end if
   end subroutine pcsi1210

end module trc_pc_k1210
